   const salesNet=vatCaptured?Number(vatSnap.captured_item_net||0)+ship.net:sale.net+ship.net;
   const estimated=paid?salesNet-cogs-fee:null;
   return {id:o.id,no:o.order_no,date:String(o.created_at||'').slice(0,10),status:o.payment_status,total:Number(o.total||0),paid,refund,fee,cogs,unmapped,costBasis:capturedComplete?'CAPTURED':'CURRENT ESTIMATE',vatBasis:vatCaptured?'CAPTURED ITEMS':'DEFAULT ESTIMATE',netSales:paid?salesNet:null,estimated,requiresReview:unmapped>0||!capturedComplete||!vatCaptured||refund>0||!paid||Number(settings.sales_vat_rate)===0};
